package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.channels.ClosedByInterruptException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

public final class TripleStoreMutationJournalTest {

	@Test
	public void appendAndReplayPreserveEveryRecordInOrder(@TempDir Path directory) throws Exception {
		TripleStoreMutationJournal journal = new TripleStoreMutationJournal(directory);
		try {
			long firstOffset = journal.append(true, true, true, 1L, 2L, 3L, 4L);
			long secondOffset = journal.append(false, false, true, 5L, 6L, 7L, 8L);

			List<TripleStoreMutationJournal.Entry> entries = new ArrayList<>();
			journal.forEach(0L, journal.size(), entries::add);

			assertEquals(0L, firstOffset);
			assertEquals(36L, secondOffset);
			assertEquals(2, entries.size());
			TripleStoreMutationJournal.Entry first = entries.get(0);
			assertEquals(firstOffset, first.offset);
			assertTrue(first.add);
			assertTrue(first.explicit);
			assertTrue(first.contextDelta);
			assertEquals(1L, first.subj);
			assertEquals(4L, first.context);

			TripleStoreMutationJournal.Entry second = entries.get(1);
			assertEquals(secondOffset, second.offset);
			assertFalse(second.add);
			assertFalse(second.explicit);
			assertTrue(second.contextDelta);
			assertEquals(5L, second.subj);
			assertEquals(8L, second.context);
		} finally {
			journal.close();
		}

		try (var files = Files.list(directory)) {
			assertTrue(files.noneMatch(path -> path.getFileName().toString().endsWith(".journal")));
		}
	}

	@Test
	public void interruptedAppendPreservesAcknowledgedSizeAndCleanup(@TempDir Path directory) throws Exception {
		Path journalPath = null;
		try (TripleStoreMutationJournal journal = new TripleStoreMutationJournal(directory)) {
			assertEquals(0L, journal.append(true, true, true, 1L, 2L, 3L, 4L));
			try (var files = Files.list(directory)) {
				journalPath = files.filter(path -> path.getFileName().toString().endsWith(".journal"))
						.findFirst()
						.orElseThrow(() -> new AssertionError("journal file was not created"));
			}

			AtomicReference<Throwable> workerFailure = new AtomicReference<>();
			Thread writer = new Thread(() -> {
				Thread.currentThread().interrupt();
				try {
					journal.append(false, true, true, 5L, 6L, 7L, 8L);
					workerFailure.set(new AssertionError("interrupted append unexpectedly completed"));
				} catch (Throwable failure) {
					workerFailure.set(failure);
				}
			}, "interrupted-journal-appender");
			try {
				writer.start();
				writer.join(TimeUnit.SECONDS.toMillis(5));
				assertFalse(writer.isAlive(), "interrupted append worker did not terminate");
				assertInstanceOf(ClosedByInterruptException.class, workerFailure.get());
				assertEquals(36L, journal.size());
				assertEquals(36L, Files.size(journalPath));
			} finally {
				if (writer.isAlive()) {
					writer.interrupt();
					writer.join(TimeUnit.SECONDS.toMillis(5));
				}
			}
		}
		assertFalse(Files.exists(journalPath));
	}

	@Test
	public void truncateAndClearSupportReplacementAndReuseWithoutForce(@TempDir Path directory) throws Exception {
		TripleStoreMutationJournal journal = new TripleStoreMutationJournal(directory);
		try {
			long firstOffset = journal.append(true, true, true, 11L, 12L, 13L, 14L);
			long discardedOffset = journal.append(false, true, false, 21L, 22L, 23L, 24L);
			assertEquals(0L, firstOffset);
			assertEquals(36L, discardedOffset);

			journal.truncate(discardedOffset);
			long replacementOffset = journal.append(false, false, true, 31L, 32L, 33L, 34L);
			List<TripleStoreMutationJournal.Entry> truncatedEntries = new ArrayList<>();
			journal.forEach(0L, journal.size(), truncatedEntries::add);
			assertEquals(2, truncatedEntries.size());
			assertEquals(firstOffset, truncatedEntries.get(0).offset);
			assertEquals(replacementOffset, truncatedEntries.get(1).offset);
			assertEquals(31L, truncatedEntries.get(1).subj);
			assertEquals(34L, truncatedEntries.get(1).context);

			journal.clear();
			assertEquals(0L, journal.size());
			long reusedOffset = journal.append(true, false, false, 41L, 42L, 43L, 44L);
			List<TripleStoreMutationJournal.Entry> reusedEntries = new ArrayList<>();
			journal.forEach(0L, journal.size(), reusedEntries::add);
			assertEquals(1, reusedEntries.size());
			assertEquals(0L, reusedOffset);
			assertEquals(41L, reusedEntries.get(0).subj);
			assertEquals(44L, reusedEntries.get(0).context);
		} finally {
			journal.close();
		}

		try (var files = Files.list(directory)) {
			assertTrue(files.noneMatch(path -> path.getFileName().toString().endsWith(".journal")));
		}
	}
}
